import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
// @ts-expect-error type error without @types/node package
import process from "node:process";
// @ts-expect-error type error without @types/node package
import { readFileSync } from "node:fs";
const host = process.env.TAURI_DEV_HOST;

/**
 * `virtual:notices`: THIRD_PARTY_NOTICES.md at the repo root (generated by
 * scripts/notices.mjs) as a string, for the notices sheet. A virtual module
 * keeps the dev server's file access to the app's own folder.
 */
function notices() {
  const id = "\0virtual:notices";
  return {
    name: "rowkery-notices",
    resolveId: (source: string) => (source === "virtual:notices" ? id : null),
    load: (loading: string) =>
      loading === id ? `export default ${JSON.stringify(readFileSync(new URL("../../THIRD_PARTY_NOTICES.md", import.meta.url), "utf8"))};` : null,
  };
}

// https://vite.dev/config/
export default defineConfig(() => ({
  plugins: [react(), notices()],

  // Vite options tailored for Tauri development and only applied in `tauri dev` or `tauri build`
  //
  // 1. prevent Vite from obscuring rust errors
  clearScreen: false,
  // 2. tauri expects a fixed port, fail if that port is not available
  server: {
    port: 1420,
    strictPort: true,
    host: host || false,
    hmr: host
      ? {
          protocol: "ws",
          host,
          port: 1421,
        }
      : undefined,
    watch: {
      // 3. tell Vite to ignore watching `src-tauri`
      ignored: ["**/src-tauri/**"],
    },
  },
}));
